def transform(grid):
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The underlying picture is symmetric about its main diagonal.
    # Where both mirrored cells are occluded, use the best-supported
    # alternative reflection/rotation symmetry of the visible picture.
    maps = [
        lambda r, c: (c, r),
        lambda r, c: (n - 1 - r, c),
        lambda r, c: (r, m - 1 - c),
        lambda r, c: (n - 1 - r, m - 1 - c),
        lambda r, c: (c, m - 1 - r),
        lambda r, c: (n - 1 - c, r),
        lambda r, c: (n - 1 - c, m - 1 - r),
        lambda r, c: (c, r),  # transpose is the known primary symmetry
    ]

    scores = []
    for f in maps:
        same = total = 0
        for r in range(n):
            for c in range(m):
                rr, cc = f(r, c)
                if 0 <= rr < n and 0 <= cc < m and grid[r][c] != 6 and grid[rr][cc] != 6:
                    total += 1
                    same += grid[r][c] == grid[rr][cc]
        scores.append(same / total if total else 0)

    for r in range(n):
        for c in range(m):
            if grid[r][c] != 6:
                continue
            choices = []
            for i, f in enumerate(maps):
                rr, cc = f(r, c)
                if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] != 6:
                    choices.append((scores[i], grid[rr][cc]))
            if choices:
                out[r][c] = max(choices)[1]
    return out
