    for r in range(n):
        for c in range(m):
            if grid[r][c] != 6 or c >= n or grid[c][r] != 6:
                continue
            if (r, c) in done:
                continue
            candidates = []
            for rr in range(n):
                if grid[rr][c] == 6:
                    continue
                score = count = 0
                for k in range(max(0, c - 8), min(m, c + 9)):
